/// Returns the begin string, message type, and route function for `SecurityStatusRequest`.
pub fn route(router: RouteOut) -> Route {
    let r = move |msg: &Message, session_id: SessionID| -> Result<(), MessageRejectErrorEnum> {
        router(SecurityStatusRequest::from_message(msg.clone()), session_id)
    };
    ("FIX.4.3", "e", Box::new(r))
}


